export class Cart {
  readonly lines: CartLine[] = [];

  constructor(
    readonly id: string,
    readonly customerId: string | null,
  ) {}

  add(line: CartLine): void {
    const existing = this.lines.find((l) => l.sku === line.sku);
    if (existing) existing.quantity += line.quantity;
    else this.lines.push({ ...line });

