  readonly sku: Sku;
  readonly quantity: number;
  status: ReservationStatus;
  expiresAt: Date;
}

export interface StockLevel {
  readonly warehouseId: number;
  readonly sku: Sku;
  onHand: number;
  reserved: number;
  /** Optimistic concurrency token; every write increments it. */
  version: number;
}

export class InsufficientStockError extends Error {
  constructor(readonly sku: string) {
    super(`Insufficient stock for ${sku}`);
  }
}

export interface InventoryService {
  /** Holds stock for every line or none; throws InsufficientStockError on the first shortfall. */
  reserve(orderId: string, lines: OrderLine[], holdMinutes: number): Promise<StockReservation[]>;
  commit(orderId: string): Promise<void>;
  release(orderId: string): Promise<void>;
}

