export enum PaymentStatus {
  Authorised = "authorised",
  Captured = "captured",
  Declined = "declined",
  Refunded = "refunded",
}

export interface Payment {
  readonly id: string;
  readonly orderId: string;
  readonly amount: Money;
  status: PaymentStatus;
  /** Reference returned by the acquirer; never a card number. */
  acquirerReference: string;
  createdAt: Date;
}

export interface CardSession {
  readonly sessionId: string;
  readonly expiresAt: Date;
}

export interface PaymentGateway {
  authorise(orderId: string, amount: Money, card: CardSession): Promise<Payment>;
  capture(payment: Payment): Promise<Payment>;
  refund(payment: Payment, amount: Money): Promise<Payment>;
}

